use std::fmt::Write;

use super::{GeneratedShader, TargetBackend};
use crate::wgsl_forge::{ForgeError, KernelSpec, Op, Schedule, FORGE_SCHEMA_VERSION};

pub fn emit_wgsl(kernel: &KernelSpec, schedule: Schedule) -> Result<GeneratedShader, ForgeError> {
    kernel.validate()?;
    let semantic_hash = kernel.semantic_hash()?;
    let mut source = String::with_capacity(2_048);
    writeln!(
        source,
        "// Generated by Qualia WGSL Forge schema {FORGE_SCHEMA_VERSION}."
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;
    writeln!(
        source,
        "// Kernel: {}@{}",
        kernel.id, kernel.semantic_version
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;
    writeln!(source, "// Semantic hash: {semantic_hash}")
        .map_err(|error| ForgeError::Emission(error.to_string()))?;
    writeln!(
        source,
        "// Schedule: workgroup={}, items={}, vector={}",
        schedule.workgroup_size, schedule.items_per_invocation, schedule.vector_width
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;

    match kernel.ops.first() {
        Some(Op::AffineF32) => emit_affine(&mut source, kernel, schedule)?,
        _ => return Err(ForgeError::Emission("unsupported operation sequence".to_string())),
    }

    let source_hash = blake3::hash(source.as_bytes()).to_hex().to_string();
    Ok(GeneratedShader {
        kernel_id: kernel.id.clone(),
        semantic_hash,
        source_hash,
        schedule,
        source,
    })
}

fn emit_affine(
    source: &mut String,
    kernel: &KernelSpec,
    schedule: Schedule,
) -> Result<(), ForgeError> {
    writeln!(
        source,
        r#"
struct AffineParams {{
    length: u32,
    scale: f32,
    bias: f32,
    _pad: u32,
}}

@group(0) @binding(0) var<storage, read> input: array<f32>;
@group(0) @binding(1) var<storage, read_write> output: array<f32>;
@group(0) @binding(2) var<uniform> params: AffineParams;

const ITEMS_PER_INVOCATION: u32 = {}u;
const VECTOR_WIDTH: u32 = {}u;

@compute @workgroup_size({})
fn {}(@builtin(global_invocation_id) gid: vec3<u32>) {{"#,
        schedule.items_per_invocation,
        schedule.vector_width,
        schedule.workgroup_size,
        kernel.entry_point
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;

    writeln!(
        source,
        "    for (var item: u32 = 0u; item < ITEMS_PER_INVOCATION; item = item + 1u) {{"
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;
    writeln!(
        source,
        "        let base = (gid.x * ITEMS_PER_INVOCATION + item) * VECTOR_WIDTH;"
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;

    match schedule.vector_width {
        1 => {
            writeln!(
                source,
                r#"        if (base < params.length) {{
            output[base] = input[base] * params.scale + params.bias;
        }}"#
            )
            .map_err(|error| ForgeError::Emission(error.to_string()))?;
        }
        2 | 4 => emit_vector_body(source, schedule.vector_width)?,
        width => {
            return Err(ForgeError::InvalidSchedule(format!(
                "unsupported affine vector width {width}"
            )))
        }
    }

    writeln!(source, "    }}\n}}").map_err(|error| ForgeError::Emission(error.to_string()))?;
    Ok(())
}

fn emit_vector_body(source: &mut String, width: u32) -> Result<(), ForgeError> {
    let components = ["x", "y", "z", "w"];
    let constructor = (0..width)
        .map(|index| format!("input[base + {index}u]"))
        .collect::<Vec<_>>()
        .join(", ");
    writeln!(
        source,
        "        if (base + {}u < params.length) {{",
        width - 1
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;
    writeln!(
        source,
        "            let value = vec{width}<f32>({constructor});"
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;
    writeln!(
        source,
        "            let transformed = value * vec{width}<f32>(params.scale) + vec{width}<f32>(params.bias);"
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;
    for index in 0..width {
        writeln!(
            source,
            "            output[base + {index}u] = transformed.{};",
            components[index as usize]
        )
        .map_err(|error| ForgeError::Emission(error.to_string()))?;
    }
    writeln!(
        source,
        r#"        }} else {{
            for (var component: u32 = 0u; component < VECTOR_WIDTH; component = component + 1u) {{
                let index = base + component;
                if (index < params.length) {{
                    output[index] = input[index] * params.scale + params.bias;
                }}
            }}
        }}"#
    )
    .map_err(|error| ForgeError::Emission(error.to_string()))?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::wgsl_forge::{BuiltinKernel, Schedule};

    #[test]
    fn emission_is_byte_deterministic() {
        let kernel = BuiltinKernel::AffineF32.spec();
        let first = emit_wgsl(&kernel, Schedule::default()).unwrap();
        let second = emit_wgsl(&kernel, Schedule::default()).unwrap();
        assert_eq!(first, second);
    }

    #[test]
    fn vector_schedule_emits_tail_guard() {
        let kernel = BuiltinKernel::AffineF32.spec();
        let generated = emit_wgsl(
            &kernel,
            Schedule {
                workgroup_size: 128,
                items_per_invocation: 4,
                vector_width: 4,
                ..Default::default()
            },
        )
        .unwrap();
        assert!(generated.source.contains("vec4<f32>"));
        assert!(generated.source.contains("index < params.length"));
    }
}
